(function(){
  function fromUnix(sec, ms){
    sec=Number(sec); if(!isFinite(sec)) return {error:'无效时间戳'};
    var d = ms? new Date(sec) : new Date(sec*1000);
    if(isNaN(d.getTime())) return {error:'无效时间戳'};
    return {value: d.toISOString()};
  }
  function toUnix(iso, ms){
    var t = Date.parse(iso); if(isNaN(t)) return {error:'无效日期'};
    return {value: ms? String(t) : String(Math.floor(t/1000))};
  }
  var API={fromUnix:fromUnix,toUnix:toUnix};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__EpochForge__=API;
})();
